script.text:


			function load$GridReport$(g) {g.add_onRender(on$GridReport$Render); g.add_commandEvent(on$GridReport$ExecuteCommand);}
			function dispose$GridReport$(g) {try {g.remove_onRender(on$GridReport$Render);} catch (ex) {}; try {g.remove_commandEven(on$GridReport$ExecuteCommand)} catch (ex) {};}

			function on$GridReport$ExecuteCommand(sender, e) {
				var g = sender, action = e.type.Action;
				switch (action) {
						case 'View':
								e.type.cancelEvent = true;
								var activeCol = g._activeColumn;
								var activeField = g._fields[activeCol] && g._fields[activeCol].Name; 
								var ma_hd = g._getItemValue(g._activeRow, activeCol);
								if (!ma_hd) break;
								var a = g._queryFilterString.split(String.fromCharCode(253));
								var ma_hdcn = (activeField == '_1so_hd') ? ma_hd : '';
								var ma_hdkt = (activeField == '_2so_hd') ? ma_hd : '';

								g._$result = [ma_hd, a[1], a[2], a[3]];
								g._navigate(g._activeCell, '&Url;');
								break;
						default:
								break;
				}
		}

			function passQueryParameters(g) {&Parameter;
				var a = [
					{Name: 'ma_hd', Value: g._$result[0]},
					{Name: 'date_from', Value: formaDate(g._$result[1])},
					{Name: 'date_to', Value: formaDate(g._$result[2])},
					{Name: 'ma_dvcs', Value: g._$result[3]},
					{Name: 'tk', Value: ''}
				];
				var session = {Memvar: a, Script: 'this._convection = true;'&Session;};
				g._passParameter(session);
			}
function formaDate(dateString) {
	return new Date( dateString.substring(0, 4), dateString.substring(4, 6) - 1, dateString.substring(6, 8)); 
}

			function on$GridReport$Render(sender, eventArgs) {
					var g = eventArgs.grid;  
					if (g._hiddenFields) {
							(window.requestAnimationFrame || window.setTimeout)(function() {
									var a = g._hiddenFields, h = '';
									for (var i = 0; i < a.length; i++) {
											setGridHiddenFields(g, a[i].Fields, a[i].Value);
											if (a[i].Value) h += (h == '' ? '' : ',') + a[i].Fields;
									}
									g._externalHiddenFields = h;
							}, 0);
					}
			}

			function setGridHiddenFields(g, c, v) {
				var a = c.split(',');
				for (var i = 0; i < a.length; i++) {
					var l = g._getColumnOrder($func.trim(a[i]));
					if (l != -1) g._setColumnVisible(l, !v);
				}
			}

		 function ViewDetail(o, n) {
				var g = o.grid, 
						p = window.location.href.split('?')[0], 
						v = g._getItemValue(g._activeRow, g._getColumnOrder('ma_kh'));
				var w = window.open(p.substring(0, p.lastIndexOf("/") + 1) + 'arkh.aspx?query=' + window.btoa(unescape(encodeURIComponent(v))));

				var tries1 = 0;
				function checkWindow() {
						tries1++;
						if (tries1 > 40) return;
						try {
								var ext = w.$find && w.$find('ctl00_FastBusiness_MainReport_searchExtender');
								if (ext) {
										ext.executeDialog(2);
										checkFilter(w, v, 0);
										return;
								}
						} catch (e) {}
						setTimeout(checkWindow, 200);
				}

				function checkFilter(win, val, tries2) {
						if (tries2 > 40) return;
						if (triggerFilterByMaHd(win, val)) return;
						setTimeout(function() { checkFilter(win, val, tries2 + 1); }, 200);
				}

				setTimeout(checkWindow, 200);
		}
		function triggerFilterByMaHd(w, value) {
				var input = w.document.getElementById('ctl00_FastBusiness_MainReport_FilterPanelTextma_kh');
				var grid = w.$find && w.$find('ctl00_FastBusiness_MainReport');
				if (!input || !grid) return false;

				input.value = value;
				var fakeEvent = { keyCode: 13, which: 13, preventDefault: function () {}, stopPropagation: function () {} };
				grid.R0(input, fakeEvent, 0);
				return true;
		}

			function beforeDrillDown(g) {g._args.cancelEvent = !($func.trim(g._getItemValue(g._activeRow, g._activeColumn)));}
			function formatDateView(c) {return String.format('{0}/{1}/{2}', c.substring(6, 8), c.substring(4, 6), c.substring(0, 4));}
